const fs = require('fs');

function main() {
    const input = fs.readFileSync(0, 'utf-8');
    let pos = 0;

    function nextInt() {
        while (pos < input.length && input.charCodeAt(pos) <= 32) {
            pos++;
        }
        if (pos >= input.length) return null;
        let res = 0;
        let sign = 1;
        if (input.charCodeAt(pos) === 45) { // '-'
            sign = -1;
            pos++;
        }
        while (pos < input.length && input.charCodeAt(pos) >= 48 && input.charCodeAt(pos) <= 57) {
            res = res * 10 + (input.charCodeAt(pos) - 48);
            pos++;
        }
        return res * sign;
    }

    const L = nextInt();
    if (L === null) return;
    const C = nextInt();
    const P = nextInt();

    const isBlack = Array.from({ length: L + 1 }, () => new Uint8Array(C + 1));
    for (let i = 0; i < P; i++) {
        const r = nextInt();
        const c = nextInt();
        isBlack[r][c] = 1;
    }

    const dr = [-1, 1, 0, 0];
    const dc = [0, 0, -1, 1];

    const candidateId = Array.from({ length: L + 1 }, () => new Int32Array(C + 1).fill(-1));
    const candidates = [];

    for (let r = 1; r <= L; r++) {
        for (let c = 1; c <= C; c++) {
            if (isBlack[r][c]) continue;
            let hasBlackNeighbor = false;
            for (let d = 0; d < 4; d++) {
                const nr = r + dr[d];
                const nc = c + dc[d];
                if (nr >= 1 && nr <= L && nc >= 1 && nc <= C && isBlack[nr][nc]) {
                    hasBlackNeighbor = true;
                    break;
                }
            }
            if (hasBlackNeighbor) {
                candidateId[r][c] = candidates.length;
                candidates.push({ r, c });
            }
        }
    }

    const numCandidates = candidates.length;
    const adj = Array.from({ length: numCandidates }, () => []);

    for (let i = 0; i < numCandidates; i++) {
        const { r, c } = candidates[i];
        if ((r + c) % 2 === 0) {
            for (let d = 0; d < 4; d++) {
                const nr = r + dr[d];
                const nc = c + dc[d];
                if (nr >= 1 && nr <= L && nc >= 1 && nc <= C) {
                    const neighborId = candidateId[nr][nc];
                    if (neighborId !== -1) {
                        adj[i].push(neighborId);
                    }
                }
            }
        }
    }

    const match = new Int32Array(numCandidates).fill(-1);
    const visited = new Uint8Array(numCandidates);

    function dfs(u) {
        for (let i = 0; i < adj[u].length; i++) {
            const v = adj[u][i];
            if (!visited[v]) {
                visited[v] = 1;
                if (match[v] === -1 || dfs(match[v])) {
                    match[v] = u;
                    return true;
                }
            }
        }
        return false;
    }

    let maxMatching = 0;
    for (let i = 0; i < numCandidates; i++) {
        const { r, c } = candidates[i];
        if ((r + c) % 2 === 0) {
            visited.fill(0);
            if (dfs(i)) {
                maxMatching++;
            }
        }
    }

    const answer = numCandidates - maxMatching;
    console.log(answer);
}

main();
